package co.edu.uts.web;import co.edu.uts.data.Database;import jakarta.servlet.http.*;import java.util.*;public class PageBean{private HttpServletRequest r;private Map<String,Object>u;public void setRequest(HttpServletRequest x){r=x;Database.init();u=(Map<String,Object>)x.getSession().getAttribute("user");}public boolean isLogged(){return u!=null;}public Map<String,Object>getUser(){return u;}public boolean can(String...a){if(u==null)return false;for(String x:a)if(x.equals(u.get("rol")))return true;return false;}public boolean active(String x){return r.getServletPath().endsWith(x+".jsp");}public String getCsrfToken(){HttpSession s=r.getSession();String x=(String)s.getAttribute("csrf");if(x==null){x=UUID.randomUUID().toString();s.setAttribute("csrf",x);}return x;}public List<Map<String,Object>>getIdeas(){return q("SELECT * FROM idea ORDER BY id DESC");}public List<Map<String,Object>>getProjects(){return q("SELECT p.*,i.titulo FROM proyecto p LEFT JOIN idea i ON i.id=p.idea_id");}public List<Map<String,Object>>getDocuments(){return q("SELECT d.*,p.codigo FROM documento d JOIN proyecto p ON p.id=d.proyecto_id");}public List<Map<String,Object>>getPqrs(){return q("SELECT * FROM pqrs ORDER BY id DESC");}public List<Map<String,Object>>getUsers(){return q("SELECT id,documento,nombre,correo,rol,activo FROM usuario");}private List<Map<String,Object>>q(String x){try{return Database.list(x);}catch(Exception e){return List.of();}}}